201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner != null) {
203	            Pet pet = owner.getPet(petId);
204	            if (pet != null) {
205	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	    }
